import Image from 'next/image';

import { cn } from '@/lib/utils';

// Generated by `npm run branding` from the mobile app's seal.
import unmMark from './unm-mark.png';

/** The UNM seal, plus the product name. */
export function BrandMark({ className, inverted = false }: { className?: string; inverted?: boolean }) {
  return (
    <div className={cn('flex items-center gap-3', className)}>
      {/* The seal's outer ring is navy: on the navy sidebar and in dark mode a faint ring keeps its edge visible.
          Unoptimized: a static file, so no /_next/image round trip. */}
      <Image
        src={unmMark}
        alt=""
        aria-hidden="true"
        width={36}
        height={36}
        unoptimized
        loading="eager"
        className={cn('size-9 shrink-0 rounded-full', inverted ? 'ring-1 ring-white/25' : 'dark:ring-1 dark:ring-white/20')}
      />
      <div className="leading-tight">
        <p className={cn('text-sm font-semibold', inverted ? 'text-white' : 'text-foreground')}>UNM Freedom Confessions</p>
        <p className={cn('text-xs', inverted ? 'text-sidebar-foreground/80' : 'text-muted-foreground')}>
          Moderation panel
        </p>
      </div>
    </div>
  );
}
